(() => {
const {PLAN,THEMES,DAY,KIND,EVE}=window.ThelaResearch;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function button(text,fn){const b=document.createElement('button');b.type='button';b.textContent=text;b.addEventListener('click',fn);return b;}
const loc=$('.field-locations');Object.entries(PLAN).forEach(([key,d])=>{const b=button(d[0],()=>pickPlace(key));b.dataset.place=key;loc.append(b);});
function pickPlace(key){$$('[data-place]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.place===key)));$('#market-area-number').textContent=String(Object.keys(PLAN).indexOf(key)+1).padStart(2,'0');$('#fieldPlanNote .tt-plan-k').textContent=PLAN[key][0];$('#fieldPlanNote .tt-plan-t').textContent=PLAN[key][1];}
$$('#fieldPlan .tt-z').forEach(z=>z.addEventListener('click',()=>pickPlace(z.dataset.z)));pickPlace('road');
THEMES.forEach((th,i)=>{const d=document.createElement('details');d.className='field-theme';const s=document.createElement('summary');s.innerHTML='<span>'+String(i+1).padStart(2,'0')+'</span>';s.append(document.createTextNode(th[0]));d.append(s);th[1].forEach(v=>{const p=document.createElement('p'),b=document.createElement('strong');b.textContent=v[0];p.append(b,document.createTextNode(v[1]));d.append(p);});d.addEventListener('toggle',()=>$('#themes-expand').textContent=$$('.field-theme').every(x=>x.open)?'Close all notes':'Open all notes');$('#field-themes').append(d);});
$('#themes-expand').addEventListener('click',()=>{const open=!$$('.field-theme').every(x=>x.open);$$('.field-theme').forEach(d=>d.open=open);});
const palette={home:'#9caa7c',src:'#dfb95d',rest:'#aaa2bc',walk:'#a9bdc9',stall:'#7b7595'};
const legend=$('.field-day-filters');Object.entries(KIND).forEach(([k,label])=>{const span=document.createElement('span');span.innerHTML='<i style="background:'+palette[k]+'"></i>'+label;legend.append(span);});
const chart=document.createElement('div');chart.className='day-river';
const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1000 320');svg.setAttribute('role','img');svg.setAttribute('aria-label','Valiben’s day from 6am to midnight, flowing from home and family through sourcing, rest and travel to the stall.');
DAY.forEach((d,i)=>{const x=35+(d[0]-6)/18*930,w=(d[1]-d[0])/18*930,y=[108,90,112,143,115,150,135,82,70][i],end=[90,112,143,115,150,135,82,70,85][i];const path=document.createElementNS(ns,'path');path.setAttribute('d',`M ${x} ${y+125} L ${x} ${y} C ${x+w*.5} ${y} ${x+w*.5} ${end} ${x+w} ${end} L ${x+w} ${end+125} C ${x+w*.5} ${end+125} ${x+w*.5} ${y+125} ${x} ${y+125} Z`);path.setAttribute('fill',palette[d[2]]);path.setAttribute('stroke','#faf7ef');path.setAttribute('stroke-width','2');path.setAttribute('tabindex','0');path.setAttribute('role','button');path.setAttribute('aria-label',d[3]+': '+KIND[d[2]]);path.addEventListener('mouseenter',()=>selectDay(i));path.addEventListener('focus',()=>selectDay(i));path.addEventListener('click',()=>selectDay(i));path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectDay(i);}});svg.append(path);});
[6,9,12,15,18,21,24].forEach(h=>{const t=document.createElementNS(ns,'text');t.setAttribute('x',35+(h-6)/18*930);t.setAttribute('y','279');t.setAttribute('text-anchor','middle');t.textContent=h===24?'12am':h===12?'12pm':h>12?(h-12)+'pm':h+'am';svg.append(t);});chart.append(svg);$('#field-day').append(chart);
const detail=document.createElement('div');detail.className='day-river-detail';detail.setAttribute('aria-live','polite');$('#field-day').append(detail);
const nav=document.createElement('div');nav.className='day-river-nav';DAY.forEach((d,i)=>{const b=button(d[3],()=>selectDay(i));b.dataset.dayEntry=i;nav.append(b);});$('#field-day').append(nav);
function selectDay(i){const d=DAY[i];detail.replaceChildren();const t=document.createElement('span');t.textContent=d[3];const h=document.createElement('h3');h.textContent=KIND[d[2]];const para=document.createElement('p');para.textContent=d[4];detail.append(t,h,para);[...svg.querySelectorAll('path')].forEach((p,n)=>p.style.opacity=n===i?'1':'.6');$$('[data-day-entry]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.dayEntry===i)));}selectDay(0);$('#field-day-count').textContent='18 documented hours · Ribbon width follows time; height is illustrative.';
let evening=0;EVE.forEach((d,i)=>{const b=button(String(i+1).padStart(2,'0')+' / '+d[0],()=>showEvening(i));b.dataset.note=i;$('.field-evening-index').append(b);});
function showEvening(i){evening=i;$$('[data-note]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.note)===i)));const a=$('#field-evening-note');a.replaceChildren();const h=document.createElement('h3');h.textContent=EVE[i][0];a.append(h);EVE[i][1].forEach(t=>{const p=document.createElement('p');p.textContent=t;a.append(p);});$('#evening-count').textContent=String(i+1).padStart(2,'0')+' / 05';$('#evening-prev').disabled=i===0;$('#evening-next').disabled=i===EVE.length-1;}
$('#evening-prev').addEventListener('click',()=>showEvening(Math.max(0,evening-1)));$('#evening-next').addEventListener('click',()=>showEvening(Math.min(EVE.length-1,evening+1)));showEvening(0);
const table=$('.rank-table'),heads=[...table.querySelectorAll('thead th')].slice(1,-1);heads.forEach((h,i)=>{const o=document.createElement('option');o.value=i;o.textContent=h.textContent;$('#rank-person').append(o);});
function rank(){const col=Number($('#rank-person').value)+1;const rows=[...table.querySelectorAll('tbody tr')].map(r=>({name:r.cells[0].textContent,rank:Number(r.cells[col].textContent)})).sort((a,b)=>a.rank-b.rank);$('#rank-priorities').replaceChildren();rows.forEach(r=>{const li=document.createElement('li');li.innerHTML='<span>'+r.rank+'</span>';li.append(document.createTextNode(r.name));$('#rank-priorities').append(li);});}$('#rank-person').addEventListener('change',rank);rank();
})();
